<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;
use App\Services\Accounting\{AccountingAccess,AccountingLedger,Decimal};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;

final class CrmLogisticsController extends Controller {
 public function __construct(private AccountingAccess $access,private AccountingLedger $ledger){}
 private function document(Request $r,int $company,int $document,bool $write=false):object {
  $this->access->authorize($r->user(),$company,'crm');$q=DB::table('crm_documents')->where(['id'=>$document,'company_id'=>$company]);if($write)$q->lockForUpdate();$doc=$q->firstOrFail();
  if($write)abort_unless($doc->source==='smartfreight'&&empty($doc->load_id)&&in_array($doc->stage,['lead','offer','order']),409,'Document is read-only or linked to execution.');return $doc;
 }
 private function record(int $company,int $document,bool $editable=true):object {
  $case=DB::table('crm_logistics_cases')->where(['company_id'=>$company,'crm_document_id'=>$document])->lockForUpdate()->firstOrFail();if($editable)abort_if($case->accepted_version_id,409,'Reopen the accepted quote before changing it.');return $case;
 }
 private function audit(Request $r,int $c,int $d,string $action,array $data=[]):void{$this->ledger->audit($c,$r->user()->id,'crm_document',$d,$action,$data);}
 public function index(Request $r,int $company,int $document){
  $doc=$this->document($r,$company,$document);$case=DB::table('crm_logistics_cases')->where(['company_id'=>$company,'crm_document_id'=>$document])->first();$quotes=$case?DB::table('crm_supplier_quotes')->where('case_id',$case->id)->orderByDesc('id')->get():collect();$versions=$case?DB::table('crm_quote_versions')->where('case_id',$case->id)->orderByDesc('version')->get():collect();if($case)$case->request=json_decode($case->request,true);foreach($versions as $v)$v->snapshot=json_decode($v->snapshot,true);return response()->json(['data'=>['case'=>$case,'quotes'=>$quotes,'versions'=>$versions,'currency'=>$doc->currency,'editable'=>$doc->source==='smartfreight'&&empty($doc->load_id)&&in_array($doc->stage,['lead','offer','order'])]]);
 }
 public function save(Request $r,int $company,int $document){
  $d=$r->validate(['expected_revision'=>['required','integer','min:0'],'request'=>['required','array:origin,destination,mode,ready_on,delivery_on,cargo,weight_kg,volume_m3,equipment,incoterm,services,supplier_deadline'],'request.origin'=>['required','string','max:255'],'request.destination'=>['required','string','max:255'],'request.mode'=>['required','in:road,air,sea,rail,multimodal'],'request.cargo'=>['required','string','max:2000'],'request.ready_on'=>['nullable','date_format:Y-m-d'],'request.delivery_on'=>['nullable','date_format:Y-m-d'],'request.supplier_deadline'=>['nullable','date_format:Y-m-d'],'request.weight_kg'=>['nullable','numeric','min:0','max:1000000000'],'request.volume_m3'=>['nullable','numeric','min:0','max:1000000000'],'request.equipment'=>['nullable','string','max:255'],'request.incoterm'=>['nullable','string','max:80'],'request.services'=>['nullable','string','max:2000']]);
  return DB::transaction(function()use($r,$company,$document,$d){$this->document($r,$company,$document,true);$case=DB::table('crm_logistics_cases')->where('crm_document_id',$document)->first();if($case){abort_if($case->accepted_version_id,409);abort_unless((int)$case->revision===(int)$d['expected_revision'],409,'Request changed. Reload.');DB::table('crm_logistics_cases')->where('id',$case->id)->update(['request'=>json_encode($d['request']),'revision'=>$case->revision+1,'updated_at'=>now()]);$id=$case->id;}else{abort_unless((int)$d['expected_revision']===0,409);$id=DB::table('crm_logistics_cases')->insertGetId(['company_id'=>$company,'crm_document_id'=>$document,'request'=>json_encode($d['request']),'created_at'=>now(),'updated_at'=>now()]);}$this->audit($r,$company,$document,'logistics_request_saved');return response()->json(['data'=>['id'=>$id]]);});
 }
 public function supplier(Request $r,int $company,int $document){
  $d=$r->validate(['supplier_name'=>['required','string','max:200'],'reference'=>['nullable','string','max:160'],'status'=>['required','in:requested,received,declined'],'currency'=>['required','regex:/^[A-Z]{3}$/'],'cost_total'=>['nullable','required_if:status,received','regex:/^\d{1,12}(\.\d{1,2})?$/'],'fx_rate'=>['nullable','regex:/^\d{1,8}(\.\d{1,8})?$/'],'fx_on'=>['nullable','date_format:Y-m-d','before_or_equal:today'],'valid_until'=>['nullable','required_if:status,received','date_format:Y-m-d'],'scope'=>['nullable','string','max:3000'],'exclusions'=>['nullable','string','max:3000']]);
  return DB::transaction(function()use($r,$company,$document,$d){$doc=$this->document($r,$company,$document,true);$case=$this->record($company,$document);if($d['status']==='received'){if($d['currency']===$doc->currency){$d['fx_rate']='1';$d['fx_on']=now()->toDateString();}else abort_unless(!empty($d['fx_on'])&&isset($d['fx_rate'])&&bccomp($d['fx_rate'],'0',8)>0,422,'Record the conversion rate and its date.');}else{$d['cost_total']=null;$d['fx_rate']=null;$d['fx_on']=null;}$id=DB::table('crm_supplier_quotes')->insertGetId($d+['case_id'=>$case->id,'recorded_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);DB::table('crm_logistics_cases')->where('id',$case->id)->increment('revision');$this->audit($r,$company,$document,'supplier_quote_recorded',['quote_id'=>$id]);return response()->json(['data'=>['id'=>$id]]);});
 }
 public function version(Request $r,int $company,int $document){
  $d=$r->validate(['supplier_quote_id'=>['required','integer'],'additional_cost'=>['required','regex:/^\d{1,12}(\.\d{1,2})?$/'],'sales_total'=>['required','regex:/^\d{1,12}(\.\d{1,2})?$/'],'valid_until'=>['required','date_format:Y-m-d','after_or_equal:today'],'allow_negative_margin'=>['sometimes','boolean']]);
  return DB::transaction(function()use($r,$company,$document,$d){$doc=$this->document($r,$company,$document,true);$case=$this->record($company,$document);$quote=DB::table('crm_supplier_quotes')->where(['case_id'=>$case->id,'id'=>$d['supplier_quote_id'],'status'=>'received'])->firstOrFail();abort_unless($quote->valid_until>=$d['valid_until'],422,'Supplier quote expires before this version.');$cost=Decimal::convert((string)$quote->cost_total,(string)$quote->fx_rate);$extra=Decimal::value($d['additional_cost']);$sales=Decimal::value($d['sales_total']);$total=bcadd($cost,$extra,2);$margin=bcsub($sales,$total,2);abort_if(bccomp($margin,'0',2)<0&&empty($d['allow_negative_margin']),422,'Confirm the negative margin.');$version=(int)DB::table('crm_quote_versions')->where('case_id',$case->id)->max('version')+1;$snapshot=['request'=>json_decode($case->request,true),'case_revision'=>$case->revision,'supplier_quote'=>(array)$quote,'currency'=>$doc->currency,'supplier_cost'=>$cost,'additional_cost'=>$extra,'total_cost'=>$total,'sales_total'=>$sales,'margin'=>$margin,'margin_percent'=>bccomp($sales,'0',2)>0?Decimal::round(bcmul(bcdiv($margin,$sales,8),'100',8)):null];$id=DB::table('crm_quote_versions')->insertGetId(['case_id'=>$case->id,'version'=>$version,'supplier_quote_id'=>$quote->id,'snapshot'=>json_encode($snapshot),'valid_until'=>$d['valid_until'],'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);$this->audit($r,$company,$document,'customer_quote_versioned',['version_id'=>$id]);return response()->json(['data'=>['id'=>$id]]);});
 }
 public function accept(Request $r,int $company,int $document,int $version){
  $d=$r->validate(['acceptance_reference'=>['required','string','max:255']]);abort_unless(trim($d['acceptance_reference']),422);
  return DB::transaction(function()use($r,$company,$document,$version,$d){$this->document($r,$company,$document,true);$case=$this->record($company,$document,false);$v=DB::table('crm_quote_versions')->where(['id'=>$version,'case_id'=>$case->id])->firstOrFail();if((int)$case->accepted_version_id===$version)return response()->json(['data'=>['id'=>$version]]);abort_if($case->accepted_version_id,409,'Another version is accepted.');abort_unless($v->valid_until>=now()->toDateString()&&(int)json_decode($v->snapshot,true)['case_revision']===(int)$case->revision,409,'Version expired or request changed. Create a new version.');DB::table('crm_quote_versions')->where('id',$version)->update(['accepted_by'=>$r->user()->id,'accepted_at'=>now(),'acceptance_reference'=>$d['acceptance_reference'],'updated_at'=>now()]);DB::table('crm_logistics_cases')->where('id',$case->id)->update(['accepted_version_id'=>$version,'updated_at'=>now()]);$this->audit($r,$company,$document,'quote_accepted',['version_id'=>$version,'reference'=>$d['acceptance_reference']]);return response()->json(['data'=>['id'=>$version]]);});
 }
 public function reopen(Request $r,int $company,int $document){$d=$r->validate(['reason'=>['required','string','max:1000']]);abort_unless(trim($d['reason']),422);return DB::transaction(function()use($r,$company,$document,$d){$this->document($r,$company,$document,true);$case=$this->record($company,$document,false);abort_unless($case->accepted_version_id,409);DB::table('crm_logistics_cases')->where('id',$case->id)->update(['accepted_version_id'=>null,'revision'=>$case->revision+1,'updated_at'=>now()]);$this->audit($r,$company,$document,'quote_reopened',['reason'=>$d['reason'],'version_id'=>$case->accepted_version_id]);return response()->json(['data'=>['id'=>$case->id]]);});}
}
